#define OP_COUNT 33

// encoded ops
#define VM_ENCODED_OPS 1
#define P1   5
#define P2   7
#define A_PC 11
#define B_PC 3

typedef struct {
  Op op;
  int32_t a;
  int32_t b;
} Instr;

typedef struct {
  int32_t id;
  const char *text;
} StrEntry;

typedef struct {
  int ret_ip;
  int locals_base;
  int locals_len;
} CallFrame;

typedef struct {
  CallFrame *data;
  int len;
  int cap;
} FrameVec;

struct VM {
  const Instr *code;
  int code_len;

  int32_t *locals;
  int locals_cap;
  int locals_top;
  int locals_base;
  int locals_len;

  int legacy_locals_len;

  int32_t stack[VM_STACK_MAX];
  int sp;

  int ip;
  int entry_ip;

  vm_extern_fn *externs;
  int externs_count;

  const StrEntry *strs;
  int strs_len;

  const int *func_locals_by_ip;
  int func_mode;
  FrameVec frames;
};

